// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// source dot        → SphereGeometry(0.12)  black
// wavy leader       → Line (black), sine-displaced path from label anchor to source
// 4 rays            → Line solid #2e86c1 (origin → active corner) + Line dashed (active → r2 corner)
// active patch      → PlaneGeometry fill #4fa3e0 op .55 + LineLoop edge #1e6fa8 (starts coincident with A1 at r1=3)
// ghost A1 / A2     → PlaneGeometry fill #7fb3d5 op .22 + LineLoop edge #2e86c1 (static at r1=3, r2=9)
// r1 / r2 arrows    → Line + 2 ConeGeometry heads + perpendicular tick Lines, gray #777 (static, ends level with patch planes)
// active r arrow    → same construction, black #111, rebuilt on slider change
// A1 / A2 label hooks→ small TubeGeometry along QuadraticBezierCurve3 + tiny Cone head, black (short annotation hooks)
// text labels       → addLabel() HTML overlays, large/high-contrast (Radio source, A1, A2, r1, r2, r, readout)

const R1 = 3, R2 = 9;
const TANB = Math.tan(THREE.MathUtils.degToRad(8));   // cone half-angle 8°
const bAxis = new THREE.Vector3(1, 0.38, 0).normalize();                 // beam direction
const uAxis = new THREE.Vector3(0, 0, 1);                                // patch horizontal side
const vAxis = new THREE.Vector3().crossVectors(uAxis, bAxis).normalize(); // patch "up" in beam plane
const patchQuat = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(uAxis, vAxis, bAxis));
const ORIGIN = new THREE.Vector3(0, 0, 0);

function beamPoint(r) { return bAxis.clone().multiplyScalar(r); }
function side(r) { return 2 * r * TANB; }
function corner(r, su, sv) {
  return bAxis.clone().multiplyScalar(r)
    .addScaledVector(uAxis, su * r * TANB)
    .addScaledVector(vAxis, sv * r * TANB);
}

/* ── Patch factory (fill + edge outline) ─────────────────────────────── */
function makePatch(fillColor, fillOpacity, edgeColor) {
  const g = new THREE.Group();
  const fill = new THREE.Mesh(
    new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({ color: fillColor, transparent: true, opacity: fillOpacity, side: THREE.DoubleSide, depthWrite: false })
  );
  const edgePts = [
    new THREE.Vector3(-0.5, -0.5, 0), new THREE.Vector3(0.5, -0.5, 0),
    new THREE.Vector3(0.5, 0.5, 0), new THREE.Vector3(-0.5, 0.5, 0)
  ];
  const edge = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints(edgePts), new THREE.LineBasicMaterial({ color: edgeColor }));
  g.add(fill, edge);
  scene.add(g);
  return g;
}
function placePatch(g, r) {
  const s = side(r);
  g.position.copy(beamPoint(r));
  g.quaternion.copy(patchQuat);
  g.scale.set(s, s, 1);
}

/* ── Source dot + wavy leader ────────────────────────────────────────── */
const source = new THREE.Mesh(new THREE.SphereGeometry(0.12, 24, 16), new THREE.MeshBasicMaterial({ color: 0x000000 }));
scene.add(source);

const srcAnchor = beamPoint(-1.5).addScaledVector(vAxis, -0.95);
{
  const wPts = [];
  for (let i = 0; i <= 60; i++) {
    const t = i / 60;
    wPts.push(srcAnchor.clone().lerp(ORIGIN, t).addScaledVector(uAxis, Math.sin(t * 5 * Math.PI) * 0.11));
  }
  scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(wPts), new THREE.LineBasicMaterial({ color: 0x000000 })));
}

/* ── Ray bundle (solid part + dashed extension, rebuilt per update) ───── */
const RAYC = 0x2e86c1;
const SIGNS = [[1, 1], [1, -1], [-1, 1], [-1, -1]];
const rayGroups = SIGNS.map(([su, sv]) => {
  const solid = new THREE.Line(new THREE.BufferGeometry(), new THREE.LineBasicMaterial({ color: RAYC }));
  const dashed = new THREE.Line(new THREE.BufferGeometry(),
    new THREE.LineDashedMaterial({ color: RAYC, dashSize: 0.28, gapSize: 0.2, transparent: true, opacity: 0.65 }));
  scene.add(solid, dashed);
  return { su, sv, solid, dashed };
});

/* ── Patches: two static ghosts + one draggable active ─────────────────
   Active patch starts coincident with A1 (r = r1 = 3), so the initial
   view shows exactly the two source-figure patches: A1 and A2.        */
const ghostA1 = makePatch(0x7fb3d5, 0.22, 0x2e86c1); placePatch(ghostA1, R1);
const ghostA2 = makePatch(0x7fb3d5, 0.22, 0x2e86c1); placePatch(ghostA2, R2);
const activePatch = makePatch(0x4fa3e0, 0.55, 0x1e6fa8);

/* ── Double-headed distance arrows with end ticks ────────────────────── */
const YUP = new THREE.Vector3(0, 1, 0);
function clearGroup(g) {
  for (const ch of [...g.children]) {
    g.remove(ch);
    ch.geometry?.dispose?.();
    if (ch.material) {
      if (Array.isArray(ch.material)) ch.material.forEach(m => m.dispose());
      else ch.material.dispose();
    }
  }
}
function buildArrow(group, a, b, color) {
  clearGroup(group);
  const dir = b.clone().sub(a).normalize();
  group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([a, b]), new THREE.LineBasicMaterial({ color })));
  for (const [p, d] of [[a, dir.clone().negate()], [b, dir]]) {
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.18, 10), new THREE.MeshBasicMaterial({ color }));
    head.quaternion.setFromUnitVectors(YUP, d);
    head.position.copy(p).addScaledVector(d, 0.09);
    group.add(head);
  }
  for (const p of [a, b]) {   // perpendicular tick marks at both ends, level with patch planes
    const t1 = p.clone().addScaledVector(vAxis, -0.14);
    const t2 = p.clone().addScaledVector(vAxis, 0.14);
    group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([t1, t2]), new THREE.LineBasicMaterial({ color })));
  }
}
const OFF_R1 = 0.95, OFF_R2 = 1.3, OFF_ACTIVE = 1.65;
// Arrow endpoints sit exactly at the source and at each patch's distance
// along the beam axis (the patch plane's axial position), so the heads and
// ticks read as measuring from source to that patch's plane.
function arrowEnds(r, off) {
  return [ORIGIN.clone().addScaledVector(vAxis, -off), beamPoint(r).addScaledVector(vAxis, -off)];
}
const r1Arrow = new THREE.Group(); scene.add(r1Arrow);
const r2Arrow = new THREE.Group(); scene.add(r2Arrow);
const rArrow = new THREE.Group(); scene.add(rArrow);
buildArrow(r1Arrow, ...arrowEnds(R1, OFF_R1), 0x777777);
buildArrow(r2Arrow, ...arrowEnds(R2, OFF_R2), 0x777777);

/* ── Small curved label hooks for A1 / A2 ──────────────────────────────
   Short hooks sitting close beside each patch, like the source figure's
   annotation arrows — not large arcs over the scene.                  */
function curvedArrow(from, to, bend, color = 0x111111) {
  const mid = from.clone().lerp(to, 0.5).add(bend);
  const curve = new THREE.QuadraticBezierCurve3(from, mid, to);
  const g = new THREE.Group();
  g.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 16, 0.016, 6, false), new THREE.MeshBasicMaterial({ color })));
  const tan = curve.getTangent(1).normalize();
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.1, 8), new THREE.MeshBasicMaterial({ color }));
  head.quaternion.setFromUnitVectors(YUP, tan);
  head.position.copy(to).addScaledVector(tan, 0.05);
  g.add(head);
  scene.add(g);
  return g;
}
// A1 hook: short curl from a point just left/up of the patch onto its top edge
const a1Anchor = corner(R1, -1, 1).addScaledVector(bAxis, -0.55).addScaledVector(vAxis, 0.5);
curvedArrow(a1Anchor.clone(), corner(R1, -1, 1).lerp(corner(R1, 1, 1), 0.35), uAxis.clone().multiplyScalar(-0.28));
// A2 hook: short curl from just above-left of the patch onto its top edge
const a2Anchor = corner(R2, -1, 1).addScaledVector(bAxis, -0.7).addScaledVector(vAxis, 0.7);
curvedArrow(a2Anchor.clone(), corner(R2, -1, 1).lerp(corner(R2, 1, 1), 0.3), uAxis.clone().multiplyScalar(-0.35));

/* ── Camera (perspective: convergence + distance shrinkage are real here) */
setCameraView({ projection: 'perspective', azimuthDeg: 40, elevationDeg: 15, rollDeg: 0, heightFraction: 0.65 });

/* ── Labels (large, high-contrast, matching the source's prominence) ──── */
addLabel('<b>Radio<br>source</b>', srcAnchor, { fontSize: '16px', offset: [-26, 34] });
addLabel('<b>A<sub>1</sub></b>', a1Anchor, { fontSize: '17px', offset: [-18, -14] });
addLabel('<b>A<sub>2</sub></b>', a2Anchor, { fontSize: '17px', offset: [-22, -18] });
{
  const [a1s, a1e] = arrowEnds(R1, OFF_R1);
  addLabel('<b>r<sub>1</sub></b>', a1s.clone().lerp(a1e, 0.5), { color: '#555', fontSize: '15px', offset: [0, 26] });
  const [a2s, a2e] = arrowEnds(R2, OFF_R2);
  addLabel('<b>r<sub>2</sub></b>', a2s.clone().lerp(a2e, 0.5), { color: '#555', fontSize: '15px', offset: [0, 28] });
}
const rLabelEntry = addLabel('<b>r</b>', ORIGIN, { color: '#111', fontSize: '15px', offset: [0, 28] });
const readoutEntry = addLabel('', corner(R1, 1, 1), {
  background: 'rgba(255,255,255,0.9)', fontSize: '14px', offset: [16, -52]
});

/* ── Reactive state ──────────────────────────────────────────────────── */
const slider = document.getElementById('distanceR');
const sliderVal = document.getElementById('distanceRVal');
const ovArea = document.getElementById('ovArea');
const ovInt = document.getElementById('ovInt');
let overlayMode = 'Area A(r)';
let currentR = parseFloat(slider.value);

function updateAnnotation() {
  readoutEntry.pos.copy(corner(currentR, 1, 1));
  const rStr = currentR.toFixed(1);
  if (overlayMode === 'Area A(r)') {
    const f = Math.pow(currentR / R1, 2);
    readoutEntry.div.innerHTML = `r = ${rStr}<br><b>A = ${f.toFixed(2)}·A₁</b>`;
  } else {
    const f = Math.pow(R1 / currentR, 2);
    readoutEntry.div.innerHTML = `r = ${rStr}<br><b>I = ${f.toFixed(2)}·I₁</b>`;
  }
}

function updateR(r) {
  currentR = r;
  placePatch(activePatch, r);
  for (const rg of rayGroups) {
    const cA = corner(r, rg.su, rg.sv);
    const cEnd = corner(R2, rg.su, rg.sv);
    rg.solid.geometry.setFromPoints([ORIGIN, cA]);
    rg.dashed.geometry.setFromPoints([cA, cEnd]);
    rg.dashed.computeLineDistances();
    rg.solid.geometry.computeBoundingSphere?.();
    rg.dashed.geometry.computeBoundingSphere?.();
  }
  const [a, b] = arrowEnds(r, OFF_ACTIVE);
  buildArrow(rArrow, a, b, 0x111111);
  rLabelEntry.pos.copy(a.clone().lerp(b, 0.5));
  sliderVal.textContent = 'r = ' + r.toFixed(1);
  updateAnnotation();
}

function setOverlay(mode) {
  overlayMode = mode;
  ovArea.classList.toggle('active', mode === 'Area A(r)');
  ovInt.classList.toggle('active', mode !== 'Area A(r)');
  updateAnnotation();
}
ovArea.addEventListener('click', () => setOverlay('Area A(r)'));
ovInt.addEventListener('click', () => setOverlay('Intensity I(r)'));

/* ── Orbit toggle ────────────────────────────────────────────────────── */
const btnOrbit = document.getElementById('btnOrbit');
btnOrbit.addEventListener('click', () => {
  controls.autoRotate = !controls.autoRotate;
  controls.autoRotateSpeed = 1.6;
  btnOrbit.classList.toggle('active', controls.autoRotate);
});

/* ── Slider ──────────────────────────────────────────────────────────── */
let _tween = null;
function cancelTween() {
  if (_tween) { cancelAnimationFrame(_tween.id); _tween = null; }
}
slider.addEventListener('input', () => {
  cancelTween();
  updateR(parseFloat(slider.value));
});

/* ── Demo steps (goToStep) ───────────────────────────────────────────── */
const STEPS = [
  {
    title: '1 · Near patch',
    narration: 'At r = r₁ the patch is small: the four rays have barely spread. The area annotation reads A₁ and all the radiated power passes through this small square.',
    state: { distanceR: R1, overlayMode: 'Area A(r)' }
  },
  {
    title: '2 · Far patch',
    narration: 'Slide the patch out to r = r₂ = 3·r₁. Its side is 3× longer, so the area is 9× larger — the same power is spread over A₂ = 9·A₁.',
    state: { distanceR: R2, overlayMode: 'Area A(r)' }
  },
  {
    title: '3 · Intensity view',
    narration: 'Switch to the intensity overlay: at r₂ the intensity is I₁/9. Tripling the distance cuts the received signal to one ninth — the inverse-square law in action.',
    state: { distanceR: R2, overlayMode: 'Intensity I(r)' }
  }
];
function tweenSliderTo(target, dur = 1200) {
  cancelTween();
  const startVal = parseFloat(slider.value);
  const t0 = performance.now();
  const step = (now) => {
    const t = Math.min(1, (now - t0) / dur);
    const e = t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; // easeInOutQuad
    const v = startVal + (target - startVal) * e;
    slider.value = v;
    updateR(v);
    if (t < 1) _tween = { id: requestAnimationFrame(step) };
    else _tween = null;
  };
  _tween = { id: requestAnimationFrame(step) };
}
function goToStep(i) {
  const s = STEPS[i];
  setOverlay(s.state.overlayMode);
  document.querySelectorAll('.demoStep').forEach(btn =>
    btn.classList.toggle('active', Number(btn.dataset.step) === i));
  document.getElementById('demoNarr').innerHTML = `<b>${s.title}</b><br>${s.narration}`;
  tweenSliderTo(s.state.distanceR);
}
window.goToStep = goToStep;
document.querySelectorAll('.demoStep').forEach(btn =>
  btn.addEventListener('click', () => goToStep(Number(btn.dataset.step))));

/* ── Hover / click explainers ────────────────────────────────────────── */
registerInteractive(source, {
  title: 'Radio source', tooltip: 'Radio source',
  body: 'A point emitter broadcasting power P uniformly. The four rays mark one fixed bundle of the radiation, so the patch area it spreads over grows with distance.'
});
registerInteractive(activePatch, {
  title: 'Receiving patch A(r)', tooltip: 'Receiving patch',
  body: 'The square cuts the ray bundle at distance r. Its side grows linearly with r, so area grows as r² and received intensity falls as I = I₁·(r₁/r)².'
});
registerInteractive(ghostA2, {
  title: 'Ghost patch A₂', tooltip: 'A₂ = 9·A₁',
  body: 'The fixed endpoint of the slider: at r₂ = 3·r₁ the bundle is 3× wider, so the intercepted square has 9× the area.'
});

/* ── Initial state: active patch coincident with A1 (r = r1), matching
   the source figure: solid rays to A1, dashed rays on to A2, two patches. */
updateR(currentR);
setOverlay('Area A(r)');
// @FIGURE_CODE_END

