const uAxis = new THREE.Vector3(0, 0, 1);                                // patch horizontal side
const vAxis = new THREE.Vector3().crossVectors(uAxis, bAxis).normalize(); // patch "up" in beam plane
const patchQuat = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(uAxis, vAxis, bAxis));
