    .addScaledVector(uAxis, su * r * TANB)
    .addScaledVector(vAxis, sv * r * TANB);
}

/* ── Patch factory (fill + edge outline) ─────────────────────────────── */
function makePatch(fillColor, fillOpacity, edgeColor) {
