// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// source dot        → SphereGeometry(0.12)  black
// wavy leader       → Line (black), sine-displaced path from label anchor to source
// 4 rays            → Line solid #2e86c1 (origin → active corner) + Line dashed (active → r2 corner)
// active patch      → PlaneGeometry fill #4fa3e0 op .55 + LineLoop edge #1e6fa8 (dragged by slider)
// ghost A1          → PlaneGeometry fill #7fb3d5 op .18 + LineLoop edge #2e86c1 (static at r1=3)
// ghost A2          → LIGHT hatched square: fill #7fb3d5 op .12 + pale diagonal hatch Lines + faint edge (static at r2=9)
// r1 / r2 arrows    → Line + 2 ConeGeometry heads + perpendicular tick Lines, BLACK #111 (static, ends level with patch planes)
// A1 / A2 label hooks→ short TubeGeometry along QuadraticBezierCurve3 + tiny Cone head, black
// text labels       → addLabel() HTML overlays (Radio source, A1, A2, r1, r2, live readout)

const R1 = 3, R2 = 9;
const TANB = Math.tan(THREE.MathUtils.degToRad(8));   // cone half-angle 8°
const bAxis = new THREE.Vector3(1, 0.38, 0).normalize();                 // beam direction
const uAxis = new THREE.Vector3(0, 0, 1);                                // patch horizontal side
const vAxis = new THREE.Vector3().crossVectors(uAxis, bAxis).normalize(); // patch "up" in beam plane
const patchQuat = new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(uAxis, vAxis, bAxis));
const ORIGIN = new THREE.Vector3(0, 0, 0);

function beamPoint(r) { return bAxis.clone().multiplyScalar(r); }
function side(r) { return 2 * r * TANB; }
function corner(r, su, sv) {
  return bAxis.clone().multiplyScalar(r)
    .addScaledVector(uAxis, su * r * TANB)
    .addScaledVector(vAxis, sv * r * TANB);
}

/* ── Patch factory (fill + optional light hatching + edge outline) ───── */
function makePatch(fillColor, fillOpacity, edgeColor, opts = {}) {
  const g = new THREE.Group();
  const fill = new THREE.Mesh(
    new THREE.PlaneGeometry(1, 1),
    new THREE.MeshBasicMaterial({ color: fillColor, transparent: true, opacity: fillOpacity, side: THREE.DoubleSide, depthWrite: false })
  );
  fill.renderOrder = 1;
  g.add(fill);
  if (opts.hatch) {
    // Light diagonal hatching so the far reference square reads as a faint
    // sketch patch, not a dominant bright panel.
    const hatchMat = new THREE.LineBasicMaterial({
      color: opts.hatchColor ?? 0xa8cbe4, transparent: true, opacity: opts.hatchOpacity ?? 0.5
    });
    for (let c = -0.75; c <= 0.751; c += 0.25) {
      const x1 = Math.max(-0.5, -0.5 - c), x2 = Math.min(0.5, 0.5 - c);
      const p1 = new THREE.Vector3(x1, x1 + c, 0.002);
      const p2 = new THREE.Vector3(x2, x2 + c, 0.002);
      const h = new THREE.Line(new THREE.BufferGeometry().setFromPoints([p1, p2]), hatchMat);
      h.renderOrder = 2;
      g.add(h);
    }
  }
  const edgePts = [
    new THREE.Vector3(-0.5, -0.5, 0), new THREE.Vector3(0.5, -0.5, 0),
    new THREE.Vector3(0.5, 0.5, 0), new THREE.Vector3(-0.5, 0.5, 0)
  ];
  const edge = new THREE.LineLoop(
    new THREE.BufferGeometry().setFromPoints(edgePts),
    new THREE.LineBasicMaterial({ color: edgeColor, transparent: true, opacity: opts.edgeOpacity ?? 1 })
  );
  edge.renderOrder = 3;
  g.add(edge);
  scene.add(g);
  return g;
}
function placePatch(g, r) {
  const s = side(r);
  g.position.copy(beamPoint(r));
  g.quaternion.copy(patchQuat);
  g.scale.set(s, s, 1);
}

/* ── Source dot + wavy leader ────────────────────────────────────────── */
